"""Utilities to print commands that reproduce a CI build locally."""

from __future__ import annotations

import os
import re
from dataclasses import dataclass, field

import click
from click.core import ParameterSource

from airflow_breeze.global_constants import APACHE_AIRFLOW_GITHUB_REPOSITORY
from airflow_breeze.utils.console import get_console

RULER = "─" * 80

# Parameters that are never relevant when reproducing a command locally.
EXCLUDED_PARAMETERS = {
    "verbose",
    "dry_run",
    "answer",
    "include_success_outputs",
    "debug_resources",
}


@dataclass
class ReproductionCommand:
    """A single shell command for local reproduction."""

    argv: list[str] = field(default_factory=list)
    comment: str | None = None


def should_print_local_reproduction() -> bool:
    """Return True only when running inside a GitHub Actions CI environment."""
    return (
        os.environ.get("CI", "").lower() == "true"
        and os.environ.get("GITHUB_ACTIONS", "").lower() == "true"
    )


def build_ci_image_reproduction_command(
    *,
    github_repository: str = APACHE_AIRFLOW_GITHUB_REPOSITORY,
    platform: str = "linux/amd64",
    python: str = "",
) -> ReproductionCommand:
    """Build the command that builds the CI image locally."""
    argv = ["breeze", "ci-image", "build"]
    if github_repository != APACHE_AIRFLOW_GITHUB_REPOSITORY:
        argv += ["--github-repository", github_repository]
    argv += ["--platform", platform]
    argv += ["--python", python]
    return ReproductionCommand(argv=argv, comment="Build the CI image locally")


def build_checkout_reproduction_commands(github_repository: str) -> list[ReproductionCommand]:
    """Build the git commands that check out the same code as CI."""
    github_ref = os.environ.get("GITHUB_REF", "")
    github_sha = os.environ.get("GITHUB_SHA", "")
    match = re.fullmatch(r"refs/pull/(\d+)/(merge|head)", github_ref)
    if match:
        number, kind = match.group(1), match.group(2)
        return [
            ReproductionCommand(
                argv=["git", "fetch", f"https://github.com/{github_repository}.git", github_ref],
                comment=(
                    f"Fetch the same code as CI (pull request {kind} ref) "
                    f"— or: gh pr checkout {number}"
                ),
            ),
            ReproductionCommand(argv=["git", "checkout", github_sha], comment=None),
        ]
    return [ReproductionCommand(argv=["git", "checkout", github_sha], comment=None)]


def _render_commands_block(commands: list[ReproductionCommand]) -> str:
    lines: list[str] = []
    number = 0
    for command in commands:
        if command.comment:
            number += 1
            lines.append(f"# {number}. {command.comment}")
        lines.append(" ".join(command.argv))
    return "\n".join(lines)


def print_local_reproduction(commands: list[ReproductionCommand]) -> None:
    """Render the reproduction commands to the console."""
    if not commands:
        return
    console = get_console()
    console.print(f"[info]{RULER}[/]")
    console.print("[info]To reproduce this CI build locally, run the following commands:[/]")
    console.print(_render_commands_block(commands))
    console.print(f"[info]{RULER}[/]")


def _preferred_long_opt(opts: list[str]) -> str | None:
    for opt in opts:
        if opt.startswith("--"):
            return opt
    return opts[0] if opts else None


def build_reproduction_command_from_context(
    ctx: click.Context,
    *,
    comment: str = "Run the same Breeze command locally",
) -> ReproductionCommand:
    """Reconstruct the CLI invocation as a :class:`ReproductionCommand` from a Click context."""
    argv: list[str] = ctx.command_path.split(" ")
    option_tokens: list[str] = []
    argument_tokens: list[str] = []

    for param in ctx.command.params:
        if isinstance(param, click.Argument):
            value = ctx.params.get(param.name)  # type: ignore[arg-type]
            if value is None:
                continue
            if isinstance(value, (list, tuple)):
                argument_tokens += [str(item) for item in value]
            else:
                argument_tokens.append(str(value))
            continue

        if param.expose_value is False:
            continue
        if param.name in EXCLUDED_PARAMETERS:
            continue

        source = ctx.get_parameter_source(param.name)  # type: ignore[arg-type]
        explicitly_set = source in (
            ParameterSource.COMMANDLINE,
            ParameterSource.ENVIRONMENT,
            ParameterSource.PROMPT,
        )
        value = ctx.params.get(param.name)  # type: ignore[arg-type]

        if getattr(param, "is_bool_flag", False) and param.secondary_opts:
            # Flag pair (--flag/--no-flag).
            if not explicitly_set:
                continue
            if value:
                positive = _preferred_long_opt(param.opts)
                if positive is not None:
                    option_tokens.append(positive)
            else:
                negative = _preferred_long_opt(param.secondary_opts)
                if negative is not None:
                    option_tokens.append(negative)
        elif getattr(param, "is_flag", False):
            # Simple boolean flag.
            if explicitly_set and value:
                positive = _preferred_long_opt(param.opts)
                if positive is not None:
                    option_tokens.append(positive)
        else:
            if not explicitly_set or value is None:
                continue
            long_opt = _preferred_long_opt(param.opts)
            if long_opt is None:
                continue
            if getattr(param, "multiple", False) and isinstance(value, (list, tuple)):
                for item in value:
                    option_tokens += [long_opt, str(item)]
            else:
                option_tokens += [long_opt, str(value)]

    argv += option_tokens
    argv += argument_tokens
    return ReproductionCommand(argv=argv, comment=comment)
